#!/usr/bin/env node
/**
 * Fails a PR when a committed image is too big for the web — catches exactly
 * the mistake that made the homepage slow: a multi-megabyte PNG checked in as
 * a seed/source asset (web/media/ itself is gitignored and regenerated by
 * Payload, so this only ever looks at source assets under the repo root and
 * web/public).
 *
 * Takes repo-relative paths one per line on stdin (the CI workflow feeds it
 * `git diff --name-only`). Run locally with:
 *   git diff --name-only --diff-filter=ACMR main... | node web/scripts/check-image-budget.mjs
 */
import { statSync } from 'node:fs'
import { extname } from 'node:path'

// Deliberately generous — this is a backstop against another skyline-hero.png
// (1.1 MB for an 828-wide photo), not a pixel-perfect budget. Payload/Sharp
// still does its own resize+WebP pass on anything uploaded through /admin;
// this only covers files committed straight to the repo.
const BUDGETS_KB = {
  '.svg': 50,
  '.gif': 500,
  '.webp': 300,
  '.avif': 300,
  '.png': 400,
  '.jpg': 400,
  '.jpeg': 400,
}

const IMAGE_EXTS = new Set(Object.keys(BUDGETS_KB))

async function main() {
  const input = await readStdin()
  const paths = input
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)

  const violations = []
  const checked = []

  for (const path of paths) {
    const ext = extname(path).toLowerCase()
    if (!IMAGE_EXTS.has(ext)) continue

    let sizeBytes
    try {
      sizeBytes = statSync(path).size
    } catch {
      // Deleted or renamed in this diff — nothing to check.
      continue
    }

    const sizeKb = sizeBytes / 1024
    const budgetKb = BUDGETS_KB[ext]
    checked.push(path)
    if (sizeKb > budgetKb) {
      violations.push({ path, sizeKb, budgetKb })
    }
  }

  if (checked.length === 0) {
    console.log('image budget: no changed image files to check.')
    return
  }

  console.log(`image budget: checked ${checked.length} changed image file(s).`)

  if (violations.length === 0) {
    console.log('image budget: all within budget.')
    return
  }

  console.error('\nimage budget: the following files are over budget:\n')
  for (const v of violations) {
    console.error(
      `  ${v.path} — ${v.sizeKb.toFixed(0)} KB (budget ${v.budgetKb} KB)`,
    )
  }
  console.error(
    '\nConvert to WebP/AVIF and/or resize to the dimensions it actually ' +
      'renders at before committing. If this file is genuinely source art ' +
      'that belongs oversized, widen its budget in web/scripts/check-image-budget.mjs ' +
      'with a comment explaining why.',
  )
  process.exitCode = 1
}

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => (data += chunk))
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

main().catch((err) => {
  console.error(err)
  process.exitCode = 1
})
